-- Look of the ForeverSim window: colours, fonts, pack textures and nine-slice frames. Everything here is drawing helpers;
-- no calculation and no access to Blizzard frames. The pack images are listed in ArtData.lua (generated by
-- _dev/tools/build_media.py); a texture that is missing there simply stays empty instead of raising an error.
ForeverRoutes.UI=ForeverRoutes.UI or{}
local UI=ForeverRoutes.UI
UI.COLOR={gold={.953,.78,.357},gold2={.788,.604,.235},text={.91,.933,.969},muted={.557,.635,.761},dim={.365,.435,.557},
 good={.31,.89,.431},bad={1,.42,.353},blue={.231,.549,1},white={1,1,1},epic={.753,.396,1},rare={.239,.584,1},fire={1,.541,.239},
 frost={.373,.769,1},arcane={.706,.608,1},line={.47,.63,.9}}
UI.FONT={body=STANDARD_TEXT_FONT or'Fonts\\FRIZQT__.TTF',title='Fonts\\MORPHEUS.TTF',num='Fonts\\ARIALN.TTF'}
local A=ForeverRoutes.Art or{}
function UI.Art(key)return A[key]end
function UI.ArtPath(key)local e=A[key];return e and (A.dir..e.file)or nil end
-- Shows image `key` in a texture region.
function UI.SetArt(tex,key)
 local e=A[key];if not e then return false end
 tex:SetTexture(A.dir..e.file);tex:SetTexCoord(e.coords[1],e.coords[2],e.coords[3],e.coords[4]);return true
end
function UI.ArtTexture(parent,layer,key,sublevel,w,h)
 local t=parent:CreateTexture(nil,layer or'ARTWORK',nil,sublevel or 0)
 UI.SetArt(t,key)
 if w then t:SetSize(w,h or w)end
 return t
end
function UI.Tint(region,color,alpha)
 if region and color then region:SetVertexColor(color[1],color[2],color[3],alpha or color[4]or 1)end
end
-- A text line. kind: body | title | num. Shadowed so it reads on any background.
function UI.Text(parent,size,color,kind,justify,layer)
 local fs=parent:CreateFontString(nil,layer or'OVERLAY')
 local path=UI.FONT[kind or'body']or UI.FONT.body
 local ok=pcall(fs.SetFont,fs,path,size or 12,'')
 if not ok or fs.GetFont and not fs:GetFont()then pcall(fs.SetFont,fs,UI.FONT.body,size or 12,'')end
 local c=color or UI.COLOR.text;fs:SetTextColor(c[1],c[2],c[3],c[4]or 1)
 fs:SetShadowColor(0,0,0,1);fs:SetShadowOffset(1,-1)
 fs:SetJustifyH(justify or'LEFT');fs:SetJustifyV('MIDDLE')
 return fs
end
-- Draws a pack image as a frame around `frame`, the way CSS border-image does: the corners keep their size, the edges
-- and the middle stretch. slices = {top,right,bottom,left} in pixels of the pack image, borders = the same four
-- widths as drawn. Returns the nine textures.
function UI.NineSlice(frame,key,slices,borders,layer,sublevel)
 local e=A[key];if not e then return nil end
 local st,sr,sb,sl=slices[1],slices[2],slices[3],slices[4]
 local bt,br,bb,bl=borders[1],borders[2],borders[3],borders[4]
 local l,r,t,b=e.coords[1],e.coords[2],e.coords[3],e.coords[4]
 local function u(x)return l+(r-l)*x/e.w end
 local function v(y)return t+(b-t)*y/e.h end
 local out={}
 local function piece(name,x0,x1,y0,y1)
  local tex=frame:CreateTexture(nil,layer or'BACKGROUND',nil,sublevel or 0)
  tex:SetTexture(A.dir..e.file);tex:SetTexCoord(u(x0),u(x1),v(y0),v(y1));out[name]=tex;return tex
 end
 local w,h=e.w,e.h
 local tl=piece('tl',0,sl,0,st);tl:SetSize(bl,bt);tl:SetPoint('TOPLEFT',frame,'TOPLEFT',0,0)
 local tr=piece('tr',w-sr,w,0,st);tr:SetSize(br,bt);tr:SetPoint('TOPRIGHT',frame,'TOPRIGHT',0,0)
 local bL=piece('bl',0,sl,h-sb,h);bL:SetSize(bl,bb);bL:SetPoint('BOTTOMLEFT',frame,'BOTTOMLEFT',0,0)
 local bR=piece('br',w-sr,w,h-sb,h);bR:SetSize(br,bb);bR:SetPoint('BOTTOMRIGHT',frame,'BOTTOMRIGHT',0,0)
 local top=piece('t',sl,w-sr,0,st);top:SetHeight(bt);top:SetPoint('TOPLEFT',frame,'TOPLEFT',bl,0);top:SetPoint('TOPRIGHT',frame,'TOPRIGHT',-br,0)
 local bot=piece('b',sl,w-sr,h-sb,h);bot:SetHeight(bb);bot:SetPoint('BOTTOMLEFT',frame,'BOTTOMLEFT',bl,0);bot:SetPoint('BOTTOMRIGHT',frame,'BOTTOMRIGHT',-br,0)
 local lef=piece('l',0,sl,st,h-sb);lef:SetWidth(bl);lef:SetPoint('TOPLEFT',frame,'TOPLEFT',0,-bt);lef:SetPoint('BOTTOMLEFT',frame,'BOTTOMLEFT',0,bb)
 local rig=piece('r',w-sr,w,st,h-sb);rig:SetWidth(br);rig:SetPoint('TOPRIGHT',frame,'TOPRIGHT',0,-bt);rig:SetPoint('BOTTOMRIGHT',frame,'BOTTOMRIGHT',0,bb)
 local mid=piece('m',sl,w-sr,st,h-sb);mid:SetPoint('TOPLEFT',frame,'TOPLEFT',bl,-bt);mid:SetPoint('BOTTOMRIGHT',frame,'BOTTOMRIGHT',-br,bb)
 return out
end
-- The frame styles of the pack. slices are measured in the pack image, borders are what the layout draws.
UI.STYLE={
 button={'button_normal',{22,28,22,28},{13,18,13,18}},
 buttonGlow={'button_glow',{22,28,22,28},{13,18,13,18}},
 buttonActive={'button_active',{24,28,24,28},{13,18,13,18}},
 buttonBig={'button_glow',{22,28,22,28},{15,22,15,22}},
 tab={'button_normal',{26,34,26,34},{16,22,16,22}},
 tabOn={'button_glow',{26,34,26,34},{16,22,16,22}},
 dropdown={'dropdown',{18,24,18,24},{12,16,12,16}},
 card={'panel_wide_small',{46,30,30,30},{30,22,22,22}},
 note={'notification_panel',{16,22,16,22},{10,14,10,14}},
 panel={'panel_square_medium',{50,34,34,34},{34,24,26,24}},
}
function UI.Style(frame,name,layer,sublevel)
 local s=UI.STYLE[name];if not s then return nil end
 return UI.NineSlice(frame,s[1],s[2],s[3],layer,sublevel)
end
function UI.Show(region,on)if on then region:Show()else region:Hide()end end

